select id, child_comment_total, like_total, first_reply_comment_id from t_comment where id in
#{commentId}
and is_deleted = 0

SELECT tc.* FROM ( SELECT parent_id, MIN(create_time) AS min_create_time FROM t_comment WHERE level = 2 AND is_deleted = 0 AND parent_id IN
#{parentId}
GROUP BY parent_id ) earliest JOIN t_comment tc ON tc.parent_id = earliest.parent_id AND tc.create_time = earliest.min_create_time AND tc.level = 2 AND tc.is_deleted = 0

